// Package catalog loads `.noml` translation catalogs for the Nolang toolchain.
//
// It is deliberately a separate package from `i18n`: `i18n` must stay free of
// dependencies so every compiler package can import it without creating a cycle,
// while the catalog reader needs the `.noml` parser that lives in `package`.
//
// Layout:
//
//	src/i18n/catalog/locales/en.noml      generated by cmd/genen (translator template)
//	src/i18n/catalog/locales/zh-CN.noml   hand-maintained translations
//	<project>/locales/<tag>.noml          optional per-project override
//
// English has no runtime catalog: `i18n.T` returns the inline default when the
// language is English, so en.noml is never read by the binary. It exists so
// translators have a complete, sorted template and so the gate can prove it is
// in sync with the source.
package catalog

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/lizongying/nolang/i18n"
	pkg "github.com/lizongying/nolang/package"
)

// LocaleDirName is the directory (relative to a project root) that may hold
// `<tag>.noml` overrides.
const LocaleDirName = "locales"

// EnCatalogHeader is the fixed preamble of the generated en.noml. The generator
// and the freshness gate both render through RenderEn, so this text exists once.
const EnCatalogHeader = "; Nolang message catalog: en\n" +
	"; GENERATED by `make i18n` from i18n.T / i18n.P / i18n.Errorf call sites.\n" +
	"; Do not edit by hand: edit the call site, then run `make i18n`.\n"

// RenderEn renders the English catalog document from id -> inline text, sorted
// by ID for a byte-stable result.
func RenderEn(entries map[string]string) string {
	ids := make([]string, 0, len(entries))
	for id := range entries {
		ids = append(ids, id)
	}
	sort.Strings(ids)

	var sb strings.Builder
	sb.WriteString(EnCatalogHeader)
	sb.WriteString("{\n")
	for _, id := range ids {
		sb.WriteString("  ")
		sb.WriteString(pkg.NomlQuote(id))
		sb.WriteString(": ")
		sb.WriteString(pkg.NomlQuote(entries[id]))
		sb.WriteString("\n")
	}
	sb.WriteString("}\n")
	return sb.String()
}

// alias maps a requested tag onto the tag whose file we actually ship. Any
// Chinese request resolves to the Simplified catalog: showing English to a
// zh-TW/zh-HK reader is a worse outcome than showing Simplified.
var alias = map[string]string{
	"zh":      "zh-CN",
	"zh-hans": "zh-CN",
	"zh-hant": "zh-CN",
	"zh-tw":   "zh-CN",
	"zh-hk":   "zh-CN",
	"zh-mo":   "zh-CN",
}

// Options configures Init.
type Options struct {
	// Lang is the explicit tag from --lang. Empty with LangSet false means "not
	// requested".
	Lang    string
	LangSet bool
	// ProjectDirs are searched for `locales/<tag>.noml` before the embedded
	// files, most specific first.
	ProjectDirs []string
	// Env reads environment variables (nil = os.Getenv).
	Env func(string) string
	// Warn receives non-fatal notices.
	Warn func(msg string)
}

// Init resolves the language and installs its catalog. It is the only function
// the binaries need to call.
func Init(o Options) error {
	return i18n.Init(i18n.Options{
		Lang:      o.Lang,
		LangSet:   o.LangSet,
		Available: Available(o.ProjectDirs),
		Env:       o.Env,
		Warn:      o.Warn,
		Canonical: Canonical,
		Load: func(tag string) (map[string]string, error) {
			return Load(o.ProjectDirs, tag)
		},
	})
}

// Canonical maps an alias onto the tag whose file exists. Unknown tags are
// returned unchanged so the caller can decide what to do.
func Canonical(tag string) string {
	if c, ok := alias[strings.ToLower(tag)]; ok {
		return c
	}
	return tag
}

// ProjectDirs returns the default search list, most specific first: the working
// directory, then the enclosing workspace root. Both binaries use this so a
// project's `locales/` override behaves the same for `no` and for the LSP.
func ProjectDirs() []string {
	wd, err := os.Getwd()
	if err != nil {
		return nil
	}
	dirs := []string{wd}
	if root, ok := findWorkspaceRoot(wd); ok && root != wd {
		dirs = append(dirs, root)
	}
	return dirs
}

// findWorkspaceRoot walks up from start looking for workspace.noml.
func findWorkspaceRoot(start string) (string, bool) {
	dir := start
	for {
		if _, err := os.Stat(filepath.Join(dir, pkg.WorkspaceFileName)); err == nil {
			return dir, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

// Available lists every tag that has a catalog, project-local first, with the
// aliases appended so the resolver can match a bare "zh" request.
func Available(projectDirs []string) []string {
	seen := map[string]bool{}
	var out []string
	add := func(tag string) {
		if tag == "" || tag == "en" || seen[tag] {
			return
		}
		seen[tag] = true
		out = append(out, tag)
	}

	for _, dir := range projectDirs {
		for _, tag := range tagsInDir(dir) {
			add(tag)
		}
	}
	for _, tag := range embeddedTags() {
		add(tag)
	}

	aliases := make([]string, 0, len(alias))
	for a := range alias {
		aliases = append(aliases, a)
	}
	sort.Strings(aliases)
	for _, a := range aliases {
		if seen[alias[a]] {
			add(a)
		}
	}
	return out
}

// Load reads the catalog for tag: project overrides first, then the embedded
// copy. A project file REPLACES the embedded one wholesale for that tag rather
// than merging key by key — predictable beats clever when the file is also the
// thing a translator edits.
func Load(projectDirs []string, tag string) (map[string]string, error) {
	tag = Canonical(tag)
	for _, dir := range projectDirs {
		if dir == "" {
			continue
		}
		path := filepath.Join(dir, LocaleDirName, tag+".noml")
		data, err := os.ReadFile(path)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return nil, fmt.Errorf("i18n: reading %s: %w", path, err)
		}
		return parseCatalog(path, data)
	}

	path := "locales/" + tag + ".noml"
	data, err := localesFS.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("i18n: no catalog for %q", tag)
	}
	return parseCatalog(path, data)
}

// parseCatalog turns a `.noml` document into a flat id -> text map. Every value
// must be a string: a nested object or array means the file was hand-edited
// wrong, and failing loudly here beats a silent half-loaded catalog.
func parseCatalog(path string, data []byte) (map[string]string, error) {
	m, err := pkg.ParseNomlMap(data)
	if err != nil {
		return nil, fmt.Errorf("i18n: %s: %w", path, err)
	}
	out := make(map[string]string, len(m))
	for k, v := range m {
		s, ok := v.(string)
		if !ok {
			return nil, fmt.Errorf("i18n: %s: value for %q must be a string, got %T", path, k, v)
		}
		out[k] = s
	}
	return out, nil
}

// tagsInDir lists the `<tag>.noml` files directly under dir/locales.
func tagsInDir(dir string) []string {
	entries, err := os.ReadDir(filepath.Join(dir, LocaleDirName))
	if err != nil {
		return nil
	}
	var out []string
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".noml") {
			continue
		}
		out = append(out, strings.TrimSuffix(e.Name(), ".noml"))
	}
	sort.Strings(out)
	return out
}
